import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Field,
  TextInput,
  DateInput,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const LOGIN_TYPE_OPTIONS: [string, string][] = [
  ['웹', '웹'],
  ['메신저', '메신저'],
  ['모바일', '모바일'],
];

export default function FnSfr03801Page({ role, notify }: PageProps) {
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [name, setName] = useState('');
  const [type, setType] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const size = 20;

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/access-logs/logins', role, undefined, { ...applied, page: pageNo, size }),
    [role, applied, pageNo],
  );

  const search = () => {
    if (from !== '' && to !== '' && from > to) {
      notify('조회 시작일이 종료일보다 늦을 수 없습니다.');
      return;
    }
    setPageNo(0);
    setApplied({
      accessedFrom: from,
      accessedTo: to === '' ? '' : to + ' 23:59:59',
      employeeName: name,
      loginType: type,
    });
  };

  const reset = () => {
    setFrom('');
    setTo('');
    setName('');
    setType('');
    setPageNo(0);
    setApplied({});
  };

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <Num value={total} />
      </section>
      <section className="box span-12">
        <h2>로그인 내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작 접속일시">
            <DateInput value={from} onChange={setFrom} />
          </Field>
          <Field label="조회 종료 접속일시">
            <DateInput value={to} onChange={setTo} />
          </Field>
          <Field label="성명">
            <TextInput value={name} onChange={setName} />
          </Field>
          <Field label="로그인 구분">
            <Select value={type} onChange={setType} options={LOGIN_TYPE_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={total} />
        {error !== '' && <ErrorText text={error} />}
        <DataTable
          columns={[
            { key: 'employeeName', label: '성명' },
            { key: 'loginId', label: '로그인 ID' },
            { key: 'accessedAt', label: '접속·사용 일시', render: (r) => <DateText value={r['accessedAt']} time /> },
            { key: 'loginIp', label: '접속 IP' },
            { key: 'loginType', label: '로그인 구분', render: (r) => <Badge value={r['loginType']} /> },
          ]}
          rows={rows}
          empty={loading ? '불러오는 중입니다.' : '조회 결과가 없습니다.'}
        />
        <Pager page={pageNo} size={size} total={total} onPage={setPageNo} />
      </section>
    </div>
  );
}
